233:         background({ readDocument(url, mode) }) { result ->
234:             if (generation != openGeneration) return@background
235:             emitOpen(result.fold({ DocumentOpenResult.Opened(it) }, { DocumentOpenResult.Failure(it.localizedDescription(iosNotice("operation_failed"))) }))
