241:     internal fun readDocument(url: NSURL, mode: DocumentOpenMode): DocumentContent {
242:         requireLocalized(url.fileURL) { iosNotice("file_url_required") }
243:         return withSecurityScope(url) {
244:             coordinatedRead(url) { actual ->
245:                 val data = fileData(actual, documentFilename(url))
246:                 val text = NSString.create(data = data, encoding = NSUTF8StringEncoding)?.toString()
247:                     ?: iosError("invalid_utf8")
248:                 val source = if (mode == DocumentOpenMode.IMPORT_COPY) temporaryDocument(url.lastPathComponent ?: "circuit.circ", text) else url
249:                 DocumentContent(reference(source, mode, sha256(data)), text)
250:             }
251:         }

313:     private fun temporaryDocument(suggestedName: String, text: String): NSURL {
314:         requireLocalized(text.encodeToByteArray().size.toULong() <= MAX_DOCUMENT_BYTES) { iosNotice("document_too_large") }
315:         val cache = NSSearchPathForDirectoriesInDomains(NSCachesDirectory, NSUserDomainMask, true).firstOrNull() as? String
316:             ?: iosError("export_prepare_failed")
317:         val directory = "$cache/LogisimExports/" + NSUUID().UUIDString
318:         checkLocalized(NSFileManager.defaultManager.createDirectoryAtPath(directory, true, null, null)) {
319:             iosNotice("export_prepare_failed")
320:         }
321:         val name = suggestedName.substringAfterLast('/').substringAfterLast('\\').ifBlank { "circuit.circ" }
322:         val url = NSURL.fileURLWithPath("$directory/${if (name.endsWith(".circ", true)) name else "$name.circ"}")
323:         checkLocalized(NSString.create(string = text).writeToURL(url, true, NSUTF8StringEncoding, null)) {
324:             iosNotice("export_write_failed")
325:         }
326:         return url

329:     private fun present(controller: UIViewController): Boolean {
330:         var host = presenter() ?: return false
331:         while (host.presentedViewController != null) host = host.presentedViewController!!
332:         if (host.view.window == null) return false
333:         controller.popoverPresentationController?.let { popover ->
334:             popover.sourceView = host.view
335:             popover.sourceRect = host.view.bounds
336:         }
337:         host.presentViewController(controller, animated = true, completion = {
338:             if (controller is UIDocumentPickerViewController) controller.presentationController?.delegate = pickerDelegate
