386: private fun <T> withSecurityScope(url: NSURL, block: () -> T): T {
387:     val acquired = url.startAccessingSecurityScopedResource()
388:     return try { block() } finally { if (acquired) url.stopAccessingSecurityScopedResource() }
389: }
