391: private fun <T> coordinatedRead(url: NSURL, block: (NSURL) -> T): T = memScoped {
392:     val failure = alloc<ObjCObjectVar<NSError?>>()
393:     failure.value = null
394:     var value: Result<T>? = null
395:     NSFileCoordinator(null).coordinateReadingItemAtURL(url, 0u, failure.ptr) { actual ->
396:         value = runCatching { block(actual ?: iosError("provider_no_access")) }
397:     }
398:     failure.value?.let {
399:         NSLog("Coordinated document read failed: %@ (%ld)", it.domain, it.code)
400:         throw LocalizedStateException(iosDocumentProviderNotice(it, documentFilename(url), iosNotice("provider_no_access")))
401:     }
402:     (value ?: iosError("provider_read_incomplete")).getOrThrow()

30:     fun attach() {
