14: final class SceneDelegate: UIResponder, UIWindowSceneDelegate {
15:     var window: UIWindow?
16:     private let store = DocumentProbe.shared
17: 
18:     func scene(_ scene: UIScene, willConnectTo session: UISceneSession, options: UIScene.ConnectionOptions) {
19:         guard let scene = scene as? UIWindowScene else { return }
20:         store.bootstrap()
21:         let controller = ControlViewController(scene: scene)
22:         let window = UIWindow(windowScene: scene)
23:         window.rootViewController = controller
24:         self.window = window
25:         window.makeKeyAndVisible()
26:         store.event("willConnect", scene: scene)
27:         for context in options.urlContexts { store.receive(context, phase: "willConnect", scene: scene) }
28:         controller.refresh()
29:     }
30: 
31:     func scene(_ scene: UIScene, openURLContexts contexts: Set<UIOpenURLContext>) {
32:         store.event("openURLContexts", scene: scene)
33:         for context in contexts { store.receive(context, phase: "openURLContexts", scene: scene) }
34:         (window?.rootViewController as? ControlViewController)?.refresh()
35:     }
36: 
37:     func sceneDidBecomeActive(_ scene: UIScene) { store.event("didBecomeActive", scene: scene) }
38:     func sceneWillResignActive(_ scene: UIScene) { store.event("willResignActive", scene: scene) }
39:     func sceneDidEnterBackground(_ scene: UIScene) { store.event("didEnterBackground", scene: scene) }

131:     func receive(_ context: UIOpenURLContext, phase: String, scene: UIScene) {
132:         let url = context.url
133:         var record: [String: Any] = ["phase": phase, "time": Date().timeIntervalSince1970,
134:             "scene": scene.session.persistentIdentifier, "url": url.absoluteString, "name": url.lastPathComponent,
135:             "fileURL": url.isFileURL, "openInPlace": context.options.openInPlace,
136:             "sourceApplication": context.options.sourceApplication ?? "", "existsBeforeRead": FileManager.default.fileExists(atPath: url.path)]
137:         let scoped = url.startAccessingSecurityScopedResource()
138:         record["securityScopeStarted"] = scoped
139:         defer { if scoped { url.stopAccessingSecurityScopedResource() } }
140:         if url.isFileURL {
141:             var coordinationError: NSError?
142:             NSFileCoordinator(filePresenter: nil).coordinate(readingItemAt: url, options: .withoutChanges, error: &coordinationError) { coordinated in
143:                 do {
144:                     let data = try Data(contentsOf: coordinated)
145:                     record["bytes"] = data.count
146:                     record["sha256"] = Self.hash(data)
147:                     record["coordinatedURL"] = coordinated.absoluteString
148:                 } catch {
149:                     let error = error as NSError
150:                     record["readErrorDomain"] = error.domain
151:                     record["readErrorCode"] = error.code
152:                 }
153:             }
154:             if let error = coordinationError {
155:                 record["coordinationErrorDomain"] = error.domain
156:                 record["coordinationErrorCode"] = error.code
157:             }
158:         }
159:         receives.append(record)
160:         persist()
